import{t as e}from"./utils-COoNfFoj.js";var t={slug:`the-holding-company`,influencerName:`The Holding Company`,influencerHandle:`@HoldingCompany.Inc`,influencerAvatarUrl:`${e}/the-holding-company-avatar.jpg`,multiAsset:!0,heroTitle:`The Holding Company's Build`,assets:[{title:`Regime Shift Monitor`,imageUrl:`${e}/the-holding-company-regime-shift-monitor.png`,quote:`I developed this Macro Sentiment Suite using only natural language instructions to visualize the invisible shift between tech growth and physical assets. It proves that complex capital rotation can be mapped instantly without a single line of code.`,promptText:`Build a Macro Sentiment Terminal for professional investors that unifies real‑time macroeconomic data, cross‑asset market moves, and news sentiment into one interactive dashboard, similar in feel to a lightweight Bloomberg terminal. The app should detect and describe the current macro regime (risk‑on/off, growth vs inflation, liquidity conditions), summarize key macro indicators (inflation, rates, growth, employment), and show a cross‑asset snapshot for equities, rates, FX, commodities, and credit. It should continuously analyze headlines and market data to infer sentiment by country, asset class, and theme, then surface a concise, PM‑style narrative of “what the market cares about most” today, likely winners/losers, and upcoming macro catalysts. The UI should be clean, dark‑mode, and queryable in natural language (e.g., “Explain current macro sentiment in US equities and the dollar”), returning institutional‑quality explanations grounded in the underlying data.`,remixUrl:`https://www.perplexity.ai/computer/a/macro-sentiment-terminal-Mm83fO5lS9GOS1bO1SZ7Vg`},{title:`Supply Chain Integrity Monitor`,imageUrl:`${e}/the-holding-company-supply-chain-integrity-monitor.png`,quote:`This Supply Chain Integrity Monitor was built entirely through Perplexity AI prompting to demonstrate real-time risk mitigation in global trade. It’s a functional example of how 'Human Insight' leads to 'AI Execution,' securing millions in physical assets through automated logistics.`,promptText:`Build a Supply Chain Integrity Monitor for large enterprises that continuously tracks suppliers, tiers, and lanes for signs of disruption, fraud, and non‑compliance using news, public data, and internal incident logs. The system should ingest unstructured signals (articles, alerts, filings), map them to specific suppliers and locations, classify disruption type (operational, geopolitical, regulatory, cyber, ESG), and estimate potential business impact across the multi‑tier network. It should present a dashboard that highlights high‑risk suppliers, emerging hotspots, and likely downstream effects on inventory, lead times, and key products, along with recommended mitigation actions (e.g., alternate suppliers, rerouting, safety‑stock changes). The interface should support natural‑language queries like “Show current risks to Tier‑2 electronics suppliers in APAC” and respond with concise, risk‑manager‑ready summaries and exportable reports.`,remixUrl:`https://www.perplexity.ai/computer/a/supply-chain-integrity-monitor-4MraIJARTpyLrLy6SxOEig`},{title:`Suez — COGH Diversion`,imageUrl:`${e}/the-holding-company-suez-cogh-diversion.png`,quote:`I built this Operational Recovery Console entirely with Computer to automate the final 10% of execution—insurance, hedging, and audit—establishing total portfolio resilience in real-time.`,promptText:`Build an Operational Recovery Console for enterprises that centralizes incident visibility and guides teams from disruption to full recovery across IT, facilities, supply chain, and customer‑facing operations. The console should ingest structured and unstructured signals (alerts, logs, tickets, outage reports, news) and group them into active incidents, estimate business and customer impact, and track status across response, stabilization, and recovery phases. It must present a clear dashboard of current incidents, affected assets and locations, SLAs, and critical path dependencies, and generate concise recovery playbooks with next‑best actions, owners, and timelines. The interface should allow natural‑language queries like “Show all critical incidents affecting customer transactions” or “What are the blockers to restoring normal operations for Site A?”, and respond with executive‑ready summaries, risk assessments, and recommended recovery steps that can be exported or shared with stakeholders.`,remixUrl:`https://www.perplexity.ai/computer/a/operational-recovery-console-s-gCEcMO8ZTjuSDC2gRZZZ7A`}]};export{t as default};
